/* ---- js/composer/commands/release-notes.js ---- */
window.CC = window.CC || {};

// `/release-notes`: the changelog the CLI caches in ~/.claude/cache/changelog.md (reader `changelog`), newest first,
// 10 versions at a time.
CC.Commands.add("release-notes", async function (ctx) {
  const util = CC.util;
  const el = util.el;
  const card = ctx.card;
  const current = ctx.composer.meta.cliVersion;
  const body = card.open("list", "Release notes", current ? "running " + current : "");
  const notes = el("div", "release-notes");
  body.appendChild(notes);
  const actions = el("div", "cmd-actions");
  const more = el("button", "chip-btn", "Older versions");
  more.type = "button";
  actions.appendChild(more);
  body.appendChild(actions);
  card.hints([]);
  const root = card.root;
  let shown = 0;

  async function load() {
    more.disabled = true;
    let r;
    try {
      r = await CC.host.reader("changelog", { skip: shown, limit: 10 });
    } catch (e) {
      notes.appendChild(el("div", "picker-empty", "Release notes unavailable: " + e.message));
      return;
    }
    if (!root.contains(notes)) {
      return;
    }
    if (r.missing) {
      notes.appendChild(el("div", "picker-empty", "No cached changelog yet (" + util.shortPath(r.path) + "). The interactive Claude Code downloads it in the background."));
      more.classList.add("hidden");
      return;
    }
    const md = r.versions.map(function (v) {
      return "## " + v.version + (v.version === current ? " (installed)" : "") + "\n\n" + v.text;
    }).join("\n\n");
    notes.appendChild(CC.markdown.render(md));
    shown += r.versions.length;
    more.classList.toggle("hidden", shown >= r.total);
    more.disabled = false;
  }

  more.addEventListener("click", load);
  await load();
});

;
/* ---- js/composer/commands/add-dir.js ---- */
window.CC = window.CC || {};

// `/add-dir [path]`: the CLI's add_directory control only stages remote mounts and the command is off in -p, so the
// daemon restarts (resuming the conversation) with the extra --add-dir; the list is kept for later resumes.
CC.Commands.add("add-dir", async function (ctx) {
  const util = CC.util;
  const el = util.el;
  const composer = ctx.composer;
  const card = ctx.card;
  const dirs = Array.isArray(composer.meta.addDirs) ? composer.meta.addDirs : [];

  if (ctx.arg === "") {
    const body = card.open("file", "Working directories", composer.meta.cwd ? util.shortPath(composer.meta.cwd) : "");
    const list = el("div", "cmd-list");
    dirs.forEach(function (d) {
      const row = el("div", "cmd-item");
      row.appendChild(el("span", "cmd-dot cmd-ok"));
      row.appendChild(el("span", "cmd-item-name", d));
      list.appendChild(row);
    });
    body.appendChild(el("div", "cmd-note", dirs.length === 0 ? "No additional directories." : "Additional directories Claude can read and edit:"));
    body.appendChild(list);
    body.appendChild(el("div", "cmd-note", "Add one with /add-dir <path> (absolute, ~/… or relative to the working directory). Claude restarts and resumes this conversation."));
    card.hints([]);
    return;
  }
  const r = await CC.host.reader("resolveDir", { cwd: composer.meta.cwd, path: ctx.arg });
  if (!r.isDir) {
    util.toast("Not a directory: " + r.path, "error");
    return;
  }
  if (dirs.indexOf(r.path) >= 0 || r.path === composer.meta.cwd) {
    util.toast("Already a working directory: " + r.path);
    return;
  }
  if (composer.isWorking()) {
    util.toast("Adding a directory restarts Claude — try again when it is idle", "error");
    return;
  }
  util.toast("Adding " + r.path + " — restarting Claude…");
  await composer.deps.restart({ addDirs: dirs.concat([r.path]) });
});

