/* ---- js/composer/commands/mcp.js ---- */
window.CC = window.CC || {};

// `/mcp [reconnect|enable|disable <server>|all]`: servers from mcp_status; a pick shows one with Reconnect
// (mcp_reconnect) and Enable / Disable (mcp_toggle, persisted like the TUI's). Enabling and reconnecting wait for the
// connection, the CLI gives up after 30 s.
CC.Commands.add("mcp", function (ctx) {
  const util = CC.util;
  const el = util.el;
  const card = ctx.card;
  const composer = ctx.composer;

  function dot(status) {
    return status === "connected" ? "ok" : status === "failed" ? "err" : status === "disabled" ? "off" : "mid";
  }

  function message(text) {
    const body = card.open("globe", "MCP servers");
    body.appendChild(el("div", "picker-empty", text));
    card.hints([]);
    return body;
  }

  async function list() {
    const body = message("Loading…");
    let r;
    try {
      r = await CC.Commands.control(composer, "mcp_status");
    } catch (e) {
      if (card.root.contains(body)) {
        message("MCP status unavailable: " + e.message);
      }
      return;
    }
    if (!card.root.contains(body)) {
      return;
    }
    const servers = r.mcpServers || [];
    const b = card.open("globe", "MCP servers", servers.length + " configured");
    card.list(b, servers.map(function (s) {
      const tools = Array.isArray(s.tools) ? s.tools.length + " tools" : "";
      return { label: s.name, dot: dot(s.status), desc: s.error || "", sub: [s.status, s.scope, tools].filter(Boolean).join(" · "), server: s };
    }), {
      search: servers.length > 8 ? "Filter servers…" : null,
      empty: "No MCP servers configured",
      action: "manage",
      onPick: function (it) {
        detail(it.server);
      },
    });
  }

  function button(text, primary, run) {
    const b = el("button", "chip-btn" + (primary ? " primary" : ""), text);
    b.type = "button";
    b.addEventListener("click", run);
    return b;
  }

  function detail(s) {
    const cfg = s.config || {};
    const body = card.open("globe", s.name, s.status);
    card.rows(body, [
      ["Status", s.status],
      ["Scope", s.scope],
      ["Transport", cfg.type],
      ["Endpoint", cfg.url || [cfg.command].concat(cfg.args || []).filter(Boolean).join(" ")],
      ["Server", s.serverInfo ? (s.serverInfo.title || s.serverInfo.name) + (s.serverInfo.version ? " " + s.serverInfo.version : "") : null],
      ["Tools", Array.isArray(s.tools) ? s.tools.map(function (t) {
        return t.name;
      }).join(", ") || "none" : null],
      ["Error", s.error],
    ]);
    const actions = el("div", "cmd-actions");
    const off = s.status === "disabled";
    actions.appendChild(button("Back", false, list));
    actions.appendChild(button(off ? "Enable" : "Disable", off, function () {
      act(s, off ? "Enabling" : "Disabling", "mcp_toggle", { enabled: off });
    }));
    if (!off) {
      actions.appendChild(button("Reconnect", true, function () {
        act(s, "Reconnecting", "mcp_reconnect", {});
      }));
    }
    body.appendChild(actions);
    card.hints([]);
    actions.lastChild.focus();
  }

  async function act(s, label, subtype, payload) {
    const body = message(label + " " + s.name + "…");
    await run(s.name, subtype, payload);
    if (card.root.contains(body)) {
      list();
    }
  }

  function run(name, subtype, payload) {
    return CC.Commands.control(composer, subtype, Object.assign({ serverName: name }, payload)).catch(function (e) {
      util.toast(name + ": " + e.message, "error");
    });
  }

  async function command(verb, target) {
    const subtype = verb === "reconnect" ? "mcp_reconnect" : "mcp_toggle";
    const payload = verb === "reconnect" ? {} : { enabled: verb === "enable" };
    const body = message((verb === "reconnect" ? "Reconnecting " : verb === "enable" ? "Enabling " : "Disabling ") + target + "…");
    let names = [target];
    if (target === "all") {
      const r = await CC.Commands.control(composer, "mcp_status").catch(function () {
        return {};
      });
      names = (r.mcpServers || []).filter(function (s) {
        return verb === "enable" ? s.status === "disabled" : s.status !== "disabled";
      }).map(function (s) {
        return s.name;
      });
    }
    await Promise.all(names.map(function (n) {
      return run(n, subtype, payload);
    }));
    if (card.root.contains(body)) {
      list();
    }
  }

  const m = /^(reconnect|enable|disable)\s+(.+)$/.exec(ctx.arg);
  if (m != null) {
    command(m[1], m[2].trim());
  } else {
    list();
  }
});

;
/* ---- js/composer/commands/plugin.js ---- */
window.CC = window.CC || {};

// `/plugin`: loaded plugins (system/init `plugins`, refreshed by reload_plugins; before the first turn the
// enabledPlugins of get_settings), Reload plugins / Reload skills. A pick opens the plugin's directory.
CC.Commands.add(["plugin", "plugins"], function (ctx) {
  const util = CC.util;
  const el = util.el;
  const card = ctx.card;
  const composer = ctx.composer;

  function button(text, run) {
    const b = el("button", "chip-btn", text);
    b.type = "button";
    b.addEventListener("click", run);
    return b;
  }

  function show(plugins, note) {
    const body = card.open("wrench", "Plugins", plugins.length + " loaded");
    const actions = el("div", "cmd-actions");
    actions.append(button("Reload plugins", reloadPlugins), button("Reload skills", reloadSkills));
    body.appendChild(actions);
    if (note) {
      body.appendChild(el("div", "cmd-note", note));
    }
    card.list(body, plugins.map(function (p) {
      const at = (p.source || "").split("@")[1] || "";
      return { label: p.name, desc: [p.version, at && at !== "builtin" ? at : ""].filter(Boolean).join(" · "),
        sub: p.path === "builtin" ? "built-in" : util.shortPath(p.path), path: p.path };
    }), {
      search: plugins.length > 8 ? "Filter plugins…" : null,
      empty: "No plugins",
      action: "open folder",
      onPick: function (it) {
        if (it.path && it.path !== "builtin") {
          CC.Commands.open(it.path);
        }
      },
    });
  }

  async function reloadPlugins() {
    const body = card.open("wrench", "Plugins");
    body.appendChild(el("div", "picker-empty", "Reloading plugins…"));
    let r;
    try {
      r = await CC.Commands.control(composer, "reload_plugins");
    } catch (e) {
      util.toast("Reload failed: " + e.message, "error");
      return;
    }
    util.toast("Reloaded: " + [[r.plugins, "plugin"], [r.commands, "skill"], [r.agents, "agent"]].map(function (p) {
      const n = (p[0] || []).length;
      return n + " " + p[1] + (n === 1 ? "" : "s");
    }).join(" · ") + (r.error_count > 0 ? " · " + r.error_count + " errors" : ""), r.error_count > 0 ? "error" : null);
    if (card.root.contains(body)) {
      show(r.plugins || [], null);
    }
  }

  async function reloadSkills() {
    try {
      const r = await CC.Commands.control(composer, "reload_skills");
      util.toast("Reloaded " + (r.skills || []).length + " skills");
    } catch (e) {
      util.toast("Reload failed: " + e.message, "error");
    }
  }

  if (Array.isArray(composer.meta.plugins)) {
    show(composer.meta.plugins, null);
    return;
  }
  const body = card.open("wrench", "Plugins");
  body.appendChild(el("div", "picker-empty", "Loading…"));
  card.hints([]);
  CC.Commands.control(composer, "get_settings").then(function (r) {
    const on = ((r.effective || {}).enabledPlugins) || {};
    if (card.root.contains(body)) {
      show(Object.keys(on).filter(function (k) {
        return on[k] === true;
      }).map(function (k) {
        return { name: k.split("@")[0], source: k };
      }), "Enabled in settings; the loaded list arrives with the first turn.");
    }
  }, function (e) {
    if (card.root.contains(body)) {
      show([], "Plugins unavailable: " + e.message);
    }
  });
});

;
/* ---- js/composer/commands/agents.js ---- */
window.CC = window.CC || {};

// `/agents`: subagent definitions from the initialize reply (name, description, model; no path or source on the wire).
// A pick shows the details; Open file tries .claude/agents/<name>.md in the project, then in ~/.claude.
CC.Commands.add("agents", function (ctx) {
  const util = CC.util;
  const el = util.el;
  const card = ctx.card;
  const composer = ctx.composer;
  const defs = composer.meta.agentDefs || [];

  function list() {
    const body = card.open("agents", "Agents", defs.length + " available");
    card.list(body, defs.map(function (a) {
      return { label: a.name, desc: util.firstLine(a.description, 200), sub: a.model ? "model: " + a.model : "", agent: a };
    }), {
      search: "Filter agents…",
      query: ctx.arg,
      empty: "No agents reported yet (start Claude first)",
      action: "details",
      onPick: function (it) {
        detail(it.agent);
      },
    });
  }

  async function openFile(a) {
    const name = a.name.replace(/[^\w.-]/g, "");
    const cwd = composer.meta.cwd || ".";
    for (const path of [cwd + "/.claude/agents/" + name + ".md", "~/.claude/agents/" + name + ".md"]) {
      try {
        await CC.openPath(path);
        return;
      } catch (e) {
        if (!/not found/.test(e && e.message)) {
          util.toast("Open failed: " + e.message, "error");
          return;
        }
      }
    }
    util.toast("No .claude/agents/" + name + ".md (built-in or plugin agent)", "error");
  }

  function detail(a) {
    const body = card.open("agents", a.name);
    card.rows(body, [["Model", a.model || "default"], ["Description", a.description]]);
    const actions = el("div", "cmd-actions");
    const back = el("button", "chip-btn", "Back");
    back.type = "button";
    back.addEventListener("click", list);
    const open = el("button", "chip-btn primary", "Open file");
    open.type = "button";
    open.addEventListener("click", function () {
      openFile(a);
    });
    actions.append(back, open);
    body.appendChild(actions);
    card.hints([]);
    open.focus();
  }

  list();
});

;
/* ---- js/composer/commands/hooks.js ---- */
window.CC = window.CC || {};

// `/hooks`: read-only get_hooks_listing (settings, session and plugin hooks in event order); a pick opens the
// settings file a hook comes from.
CC.Commands.add("hooks", async function (ctx) {
  const util = CC.util;
  const el = util.el;
  const card = ctx.card;
  const composer = ctx.composer;
  const body = card.open("terminal", "Hooks");
  body.appendChild(el("div", "picker-empty", "Loading…"));
  card.hints([]);
  let r;
  try {
    r = await CC.Commands.control(composer, "get_hooks_listing");
  } catch (e) {
    body.textContent = "";
    body.appendChild(el("div", "picker-empty", "Hooks unavailable: " + e.message));
    return;
  }
  if (!card.root.contains(body)) {
    return;
  }
  const hooks = r.hooks || [];
  const order = (r.eventCatalog || r.events || []).map(function (ev) {
    return ev.name;
  });
  hooks.sort(function (a, b) {
    return order.indexOf(a.event) - order.indexOf(b.event);
  });
  const b = card.open("terminal", "Hooks", hooks.length + " configured");
  const policy = r.policy || {};
  if (policy.allDisabled || policy.disabledByPolicy) {
    b.appendChild(el("div", "cmd-note", "Hooks are disabled" + (policy.disabledByPolicy ? " by policy." : " (disableAllHooks).")));
  } else if (policy.managedOnly || policy.pluginOnly) {
    b.appendChild(el("div", "cmd-note", "Only " + (policy.managedOnly ? "managed" : "plugin") + " hooks run."));
  }
  card.list(b, hooks.map(function (h) {
    return {
      label: h.event + (h.matcher ? " · " + h.matcher : ""),
      desc: util.firstLine(h.displayText || h.commandText, 200),
      sub: (h.sourceLabel || h.source || "") + (h.timeout ? " · timeout " + h.timeout + " s" : ""),
      title: h.commandText || h.displayText,
      path: CC.Commands.settingsFile(composer, h.source),
    };
  }), {
    search: "Filter hooks…",
    query: ctx.arg,
    empty: "No hooks configured",
    action: "open settings file",
    onPick: function (it) {
      if (it.path != null) {
        CC.Commands.open(it.path);
      } else {
        util.toast("This hook has no settings file to open");
      }
    },
  });
});

;
/* ---- js/composer/commands/permissions.js ---- */
window.CC = window.CC || {};

// `/permissions`: read-only list_permission_rules (allow, ask, deny with their source) and the permission mode; a pick
// opens the rule's settings file. update_settings refuses `permissions` keys, so rules are edited in the file.
CC.Commands.add(["permissions", "allowed-tools"], async function (ctx) {
  const util = CC.util;
  const el = util.el;
  const card = ctx.card;
  const composer = ctx.composer;
  const SOURCES = {
    userSettings: "user settings", projectSettings: "project settings", localSettings: "local settings",
    policySettings: "managed policy", flagSettings: "--settings flag", cliArg: "command-line flag", command: "slash command", session: "this session",
  };
  const ORDER = ["allow", "ask", "deny"];
  const body = card.open("shield", "Permissions");
  body.appendChild(el("div", "picker-empty", "Loading…"));
  card.hints([]);
  let r;
  try {
    r = await CC.Commands.control(composer, "list_permission_rules");
  } catch (e) {
    body.textContent = "";
    body.appendChild(el("div", "picker-empty", "Permission rules unavailable: " + e.message));
    return;
  }
  if (!card.root.contains(body)) {
    return;
  }
  const st = r.state || {};
  const rules = (st.rules || []).slice().sort(function (a, b) {
    return ORDER.indexOf(a.behavior) - ORDER.indexOf(b.behavior);
  });
  const counts = ORDER.map(function (k) {
    return rules.filter(function (x) {
      return x.behavior === k;
    }).length + " " + k;
  }).join(" · ");
  const b = card.open("shield", "Permissions", counts);
  card.rows(b, [
    ["Mode", composer.meta.permissionMode],
    ["Directories", [st.originalCwd || composer.meta.cwd].concat((st.workspaceDirectories || []).map(function (d) {
      return d.path || d;
    })).filter(Boolean).join(", ")],
  ].concat(st.managedOnly ? [["Policy", "only managed rules apply"]] : []));
  card.list(b, rules.map(function (x) {
    const d = x.description;
    return {
      label: x.rule,
      dot: { allow: "ok", ask: "mid", deny: "err" }[x.behavior],
      desc: d ? d.prefix + (d.emphasis || "") + (d.suffix || "") : "",
      sub: x.behavior + " · " + (SOURCES[x.source] || x.source),
      path: CC.Commands.settingsFile(composer, x.source),
    };
  }), {
    search: "Filter rules…",
    query: ctx.arg,
    empty: "No permission rules",
    action: "open settings file",
    onPick: function (it) {
      if (it.path != null) {
        CC.Commands.open(it.path);
      } else {
        util.toast("This rule has no settings file to open");
      }
    },
  });
});

;
/* ---- js/composer/commands/memory.js ---- */
window.CC = window.CC || {};

// `/memory`: instruction files and auto memories from get_memory_dialog, token counts from get_context_usage
// `memoryFiles` (also the fallback list); a pick opens the file.
CC.Commands.add("memory", async function (ctx) {
  const util = CC.util;
  const el = util.el;
  const card = ctx.card;
  const composer = ctx.composer;
  const body = card.open("brain", "Memory");
  body.appendChild(el("div", "picker-empty", "Loading…"));
  card.hints([]);
  const res = await Promise.allSettled([
    CC.Commands.control(composer, "get_memory_dialog"),
    CC.Commands.control(composer, "get_context_usage", { detail: "summary" }),
  ]);
  if (!card.root.contains(body)) {
    return;
  }
  const dialog = res[0].status === "fulfilled" ? res[0].value : null;
  const loaded = res[1].status === "fulfilled" ? res[1].value.memoryFiles || [] : [];
  if (dialog == null && res[1].status === "rejected") {
    body.textContent = "";
    body.appendChild(el("div", "picker-empty", "Memory unavailable: " + res[0].reason.message));
    return;
  }
  const tokens = {};
  loaded.forEach(function (f) {
    tokens[f.path] = f.tokens;
  });
  const cwd = composer.meta.cwd;
  function size(path) {
    return tokens[path] != null ? util.fmtTokens(tokens[path]) + " tokens" : "";
  }
  let items;
  if (dialog != null) {
    items = (dialog.files || []).map(function (f) {
      return { label: f.label, desc: util.shortPath(f.path, cwd), sub: f.exists ? [size(f.path), f.description].filter(Boolean).join(" · ") : "not created yet", path: f.exists ? f.path : null };
    }).concat((dialog.folders || []).map(function (f) {
      return { label: f.label, desc: util.shortPath(f.path, cwd), sub: f.description, path: f.path };
    }), (dialog.memories || []).map(function (m) {
      return { label: m.name, desc: m.description || "", sub: [m.type, size(m.path), m.modified_ms ? new Date(m.modified_ms).toLocaleDateString() : ""].filter(Boolean).join(" · "), path: m.path };
    }));
  } else {
    items = loaded.map(function (f) {
      return { label: util.shortPath(f.path, cwd), desc: f.type, sub: size(f.path), path: f.path };
    });
  }
  const auto = dialog && dialog.auto_memory ? "auto memory " + dialog.auto_memory.status : "";
  const b = card.open("brain", "Memory", [loaded.length + " loaded", auto].filter(Boolean).join(" · "));
  card.list(b, items, {
    search: "Filter memory…",
    query: ctx.arg,
    empty: "No memory files",
    action: "open",
    onPick: function (it) {
      if (it.path != null) {
        CC.Commands.open(it.path);
      } else {
        util.toast(it.label + " does not exist yet");
      }
    },
  });
});

